-- 백업 저장 여부 확인(읽기 전용). backup_rows가 30이고 lengths_match가 30이면 원문 백업이 온전하다.
SELECT count(*) AS backup_rows,
       count(*) FILTER (WHERE (id, char_length(detailed_meaning)) IN ((1,385),(26,193),(51,592),(76,644),(101,407),(126,616),(151,382),(176,427),(201,519),(226,1199),(251,451),(276,433),(301,1012),(326,767),(351,449),(376,736),(401,509),(426,133),(451,571),(476,554),(501,365),(526,839),(551,458),(576,358),(601,824),(626,901),(651,523),(676,288),(701,159),(726,451))) AS lengths_match
FROM public.words_detailed_meaning_backup_v1
WHERE id IN (1,26,51,76,101,126,151,176,201,226,251,276,301,326,351,376,401,426,451,476,501,526,551,576,601,626,651,676,701,726);
